const ELEMENT_PROP_KEYS = new Set(["theme","stage","hold","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  stage: 44,
  hold: 30,
  fontFamily: "Space Grotesk",
  scale: 1,
  delay: 0,
  speed: 1,
};

type HotStageElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof HotStageBase>;

const HotStageInner = forwardRef<
  HTMLDivElement,
  HotStageElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<HotStage>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <HotStageBase
          {...(componentProps as unknown as ComponentProps<typeof HotStageBase>)}
        />
      </div>
    </Sequence>
  );
});

export const HotStage = Interactive.withSchema({
  Component: HotStageInner,
  componentName: "<HotStage>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
